use lg_cli::args::Command;
use lg_cli::commands::run;
use lg_cli::Settings;

#[test]
fn disc_l22() {
    let extrato = "data;descricao;valor\n2024-02-01;A;-1,00\n2024-05-01;B;-2,00\n";
    let cmd = Command::Period { by: "exercicio".into(), tax_rate: None };
    let out = run(&cmd, &Settings::default(), &[("x.csv", extrato)], None).unwrap();
    assert!(out.contains("FY2024"), "{out}");
}
